import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String x = sc.next();
        int k = sc.nextInt();
        int n = x.length();
        long[][] dp = new long[1 << n][k];

        // 初始化：只选一张卡片且不为 '0'
        for (int i = 0; i < n; i++) {
            if (x.charAt(i) != '0') {
                dp[1 << i][(x.charAt(i) - '0') % k] = 1;
            }
        }

        // 状态转移
        for (int i = 0; i < (1 << n); i++) {
            for (int j = 0; j < n; j++) {
                if ((i >> j & 1) == 1) continue;
                for (int rem = 0; rem < k; rem++) {
                    if (dp[i][rem] == 0) continue;
                    int nxt = (rem * 10 + (x.charAt(j) - '0')) % k;
                    dp[i | (1 << j)][nxt] += dp[i][rem];
                }
            }
        }

        long ans = dp[(1 << n) - 1][0];

        // 去重
        int[] cnt = new int[10];
        for (char ch : x.toCharArray()) {
            cnt[ch - '0']++;
        }
        for (int d = 0; d < 10; d++) {
            for (int v = 1; v <= cnt[d]; v++) {
                ans /= v;
            }
        }

        System.out.println(ans);
    }
}
